def md5_utf8(x):
    if isinstance(x, str):
        x = x.encode("utf-8")
    return hashlib.md5(x).hexdigest()

def sha_utf8(x):
    if isinstance(x, str):
        x = x.encode("utf-8")
    return hashlib.sha1(x).hexdigest()

def get_md5(text: str | bytes) -> bytes:
    if isinstance(text, str):
        text = text.encode("utf-8")
    md5 = hashlib.md5()
    md5.update(text)
    return md5.digest()
